import type { CodegenConfig } from '@graphql-codegen/cli';
import path from 'path';

// Determine the GraphQL schema source.
// Set GRAPHQL_SCHEMA to point at a live endpoint or a custom file path.
// Falls back to the local schema.graphql file generated by `nx run db:print-schema`
// so codegen works without a running server (e.g. during `make pre-commit`).
// Use __dirname-relative path so this works regardless of Nx cwd setting.
const schemaSource =
  process.env.GRAPHQL_SCHEMA ||
  path.resolve(__dirname, '../../lambdas/db/schema.graphql');

console.log(`🔗 API GraphQL CodeGen using schema: ${schemaSource}`);

const config: CodegenConfig = {
  overwrite: true,
  schema: schemaSource,
  documents: [
    'src/shared/hello.query.graphql',
    'src/resources/players/*.graphql',
  ],
  generates: {
    'src/shared/graphql.generated.ts': {
      config: {
        documentVariableSuffix: '',
        scalars: {
          BigInt: 'string',
          Datetime: 'string',
          Cursor: 'string',
          JSON: 'any',
          UUID: 'string',
        },
      },
      plugins: [
        {
          add: {
            content: '/* eslint-disable */',
          },
        },
        'typescript',
        'typescript-operations',
        'typescript-react-apollo',
      ],
    },
  },
  hooks: {
    // Invoke the fix-apollo script directly (not via `pnpm -w run`, which
    // would force cwd to the workspace root) so it keeps this package's cwd
    // and the file path graphql-codegen appends to this command resolves to
    // *this* package's own generated file, not the whole monorepo's set.
    // See scripts/fix-apollo-codegen.js for why that scoping matters (LS-9958).
    afterAllFileWrite: [
      `node ${path.resolve(__dirname, '../../scripts/fix-apollo-codegen.js')}`,
      'prettier --write',
    ],
  },
};

export default config;
